#ifndef E64_MENU_THEME_H
#define E64_MENU_THEME_H

/* C64 palette roles. Keep native components on this palette, not RGB. */
#define E64_MENU_BACKGROUND 0
#define E64_MENU_TEXT 1
#define E64_MENU_SELECTED_TEXT 0
#define E64_MENU_HIGHLIGHT 3
#define E64_MENU_BORDER 14
#define E64_MENU_HEADING E64_MENU_HEADER
#define E64_MENU_HEADER 7
#define E64_MENU_FOOTER 8
#define E64_MENU_SEPARATOR 9
#define E64_MENU_SUBMENU_SEPARATOR 9 /* Approved E64 brown. */
#define E64_MENU_EXPANDABLE_SEPARATOR 11 /* Preserve original C64 dark gray. */
#define E64_MENU_INTERNAL_SEPARATOR 11 /* Unrelated dialog dividers. */
#define E64_MENU_DEVICE_SEPARATOR 12 /* Preserve brighter device boundaries. */
#define E64_MENU_SAVED E64_MENU_CONNECTED /* Existing E64 green. */
#define E64_MENU_CONNECTED 5
#define E64_MENU_DISCONNECTED 2
#define E64_MENU_DISABLED 11
#define E64_MENU_DISABLED_VALUE 12
#define E64_MENU_DESCRIPTION E64_MENU_TEXT
#define E64_MENU_INFORMATION 3

/* Whole CHARGEN cells: the header/footer use the content edges, and the
 * surrounding frame occupies the next cell outside those content bounds. */
#define E64_MENU_CELL 8
#define E64_MENU_HALF_CELL (E64_MENU_CELL / 2)
#define E64_MENU_HEADER_SIDE_CELLS 6
#define E64_MENU_ROOT_TITLE "E64"
#define E64_MENU_FRAME_PADDING E64_MENU_CELL
#define E64_MENU_ROW_HEIGHT E64_MENU_CELL
#define E64_MENU_INDENT E64_MENU_CELL
#define E64_MENU_SIDE_GAP E64_MENU_CELL
#define E64_MENU_ROW_MARGIN E64_MENU_CELL
#define E64_MENU_HEADER_ROWS 3
#define E64_MENU_FOOTER_ROWS 3
#define E64_MENU_ROOT_TOP_INSET (E64_MENU_HEADER_ROWS * E64_MENU_CELL - E64_MENU_HALF_CELL)
#define E64_MENU_ROOT_BOTTOM_INSET ((E64_MENU_FOOTER_ROWS - 1) * E64_MENU_CELL)
/* Retain the established help-page optical inset above its 8px rows. */
#define E64_MENU_HELP_OPTICAL_INSET 5
#define E64_MENU_HELP_RESERVED_ROWS 2
#define E64_MENU_CREATE_DISK_TOP_INSET E64_MENU_CELL
#define E64_MENU_ABOUT_TOP_ROWS 2
#define E64_MENU_CONFIG_LIST_COLS 38
#define E64_MENU_SELECTION_MIN_COLS 6
#define E64_MENU_SELECTION_MAX_COLS 40
#define E64_MENU_SELECTION_PADDING E64_MENU_CELL
#define E64_MENU_SELECTION_EXTRA_RIGHT E64_MENU_CELL
#define E64_MENU_SELECTION_TAG "OPTIONS"
#define E64_MENU_CONFIG_NAME_COLS (CONFIGS_MAX_NAME_LEN + 4)
#define E64_MENU_CONFIG_NAME_TAG "CONFIG_NAME"
#define E64_MENU_CONFIG_LIST_TAG "CONFIG_LIST"
#define E64_MENU_TEXT_CURSOR_BLINK_US 333333UL

/* Uppercase/graphics screen codes from the original C64 CHARGEN. */
#define E64_MENU_HORIZONTAL 0x40
#define E64_MENU_VERTICAL 0x5D
#define E64_MENU_ROUND_TL 0x55
#define E64_MENU_ROUND_TR 0x49
#define E64_MENU_ROUND_BL 0x4A
#define E64_MENU_ROUND_BR 0x4B
#define E64_MENU_SQUARE_TL 0x70
#define E64_MENU_SQUARE_TR 0x6E
#define E64_MENU_SQUARE_BL 0x6D
#define E64_MENU_SQUARE_BR 0x7D
#define E64_MENU_LEFT_T 0x6B
#define E64_MENU_RIGHT_T 0x73
#define E64_MENU_TOP_T 0x72
#define E64_MENU_BOTTOM_T 0x71
#define E64_MENU_LEFT_ARROW 0x1F
#define E64_MENU_OPTION_MARKER "*"

/* Legacy grayscale palette slots for the separate Pi Zero Lite build. */
#ifdef RASPI_LITE
#define BG_COLOR 20
#define FG_COLOR 21
#define DISABLED_COLOR 23
#define READ_ONLY_DESCRIPTION_COLOR 21
#define HILITE_COLOR 22
#define BORDER_COLOR 24
#define PANEL_COLOR 25
#else
#define BG_COLOR E64_MENU_BACKGROUND
#define FG_COLOR E64_MENU_TEXT
#define DISABLED_COLOR E64_MENU_DISABLED
#define READ_ONLY_DESCRIPTION_COLOR E64_MENU_DESCRIPTION
#define HILITE_COLOR E64_MENU_HIGHLIGHT
#define BORDER_COLOR E64_MENU_BORDER
#define PANEL_COLOR E64_MENU_BORDER
#endif
#define TRANSPARENT_COLOR 16

/* Existing renderer role names are aliases, never independent colors. */
#define E64_SEPARATOR_COLOR E64_MENU_SEPARATOR
#define E64_BANNER_TEXT_COLOR E64_MENU_FOOTER
#define E64_TITLE_TEXT_COLOR E64_MENU_HEADER
#define E64_CONNECTED_COLOR E64_MENU_CONNECTED
#define E64_DISCONNECTED_COLOR E64_MENU_DISCONNECTED
#define E64_HRULE_GLYPH E64_MENU_HORIZONTAL
#define E64_LEFT_T_GLYPH E64_MENU_LEFT_T
#define E64_RIGHT_T_GLYPH E64_MENU_RIGHT_T
#endif
